function generate_digest(val: uint64, reg_type: RegType) -> uint12:
    match reg_type:
        case INT:
            trailing_zeros = count_trailing_zeros(val) & 0x3F
            leading_zeros = count_leading_zeros(val) & 0x3F
            lsb6 = val & 0x3F
            // Overlapping XOR fold per Figure 6(a)
            digest = trailing_zeros ^ (leading_zeros << 3) ^ (lsb6 << 6)
            return digest & 0xFFF
        case FP:
            // Format classification via MSBs per Figure 6(b)
            if is_fp16(val):
                // Val[15:13]: sign + 2 exp bits at digest[5:3]
                return (extract_bits(val, 15, 13) << 3) & 0xFFF
            elif is_fp32(val):
                // Val[31:26]: sign + 5 exp bits at digest[8:3]
                return (extract_bits(val, 31, 26) << 3) & 0xFFF
            else: // FP64
                // Val[63:55]: sign + 8 exp bits at digest[11:3]
                return (extract_bits(val, 63, 55) << 3) & 0xFFF
        case FLAG:
            // Replicate 4 condition flags 3 times per Figure 6(c)
            flags4 = val & 0xF
            return (flags4 << 8) | (flags4 << 4) | flags4

function predict_sr(pc: uint64) -> int32:
    sR = 0
    for bank_idx in 0..7:
        // 1. Evaluate usefulness for all registers assigned to this bank
        bank_regs = get_registers_for_bank(bank_idx) // 9 regs for bank 0, 8 for banks 1..7
        ut0_idx = hash_ut0(pc)
        ut1_idx = hash_ut1(pc)
        ut2_idx = hash_ut2(pc)

        best_reg = null
        max_useful = -INFINITY

        for reg in bank_regs:
            if register_tracking_table[reg].valid == 1 and register_tracking_table[reg].decay_ctr > 0:
                useful_weight = ut_tables[bank_idx].UT0[ut0_idx][reg] +
                                ut_tables[bank_idx].UT1[ut1_idx][reg] +
                                ut_tables[bank_idx].UT2[ut2_idx][reg]
                if useful_weight > max_useful:
                    max_useful = useful_weight
                    best_reg = reg

        // 2. Query prediction weight tables if an available register exists
        if best_reg != null:
            digest = register_tracking_table[best_reg].payload[11:0]
            h0 = hash_wt0(pc, digest) // 9 bits (512 entries)
            h1 = hash_wt1(pc, digest) // 8 bits (256 entries)
            h2 = hash_wt2(pc, digest) // 7 bits (128 entries)

            wt_sum = wt_tables[bank_idx].WT0[h0] +
                     wt_tables[bank_idx].WT1[h1] +
                     wt_tables[bank_idx].WT2[h2]

            // Scale bank contribution: x2.5 if useful (max_useful > 0), else x0
            if max_useful > 0:
                bank_contrib = int(wt_sum * 2.5) // implemented as (wt_sum * 5) >> 1
            else:
                bank_contrib = 0
            sR += bank_contrib
        else:
            sR += 0

    return sR

function on_instruction_decode(inst: Instruction):
    // Decrement decay counters for all valid registers
    for r in 0..64:
        if register_tracking_table[r].valid == 1:
            if register_tracking_table[r].decay_ctr > 0:
                register_tracking_table[r].decay_ctr -= 1
            if register_tracking_table[r].decay_ctr == 0:
                register_tracking_table[r].valid = 0

    // If instruction modifies destination register, mark pending with ROB index
    if inst.has_dest_reg:
        r_dest = inst.dest_reg_id
        register_tracking_table[r_dest].valid = 0
        register_tracking_table[r_dest].payload = inst.rob_index & 0x3FFF // 14-bit tag
        register_tracking_table[r_dest].decay_ctr = 256

function on_instruction_complete(rob_index: uint14, dest_reg: uint8, result_val: uint64, reg_type: RegType):
    // Overwrite payload if ROB tag matches
    if register_tracking_table[dest_reg].valid == 0 and register_tracking_table[dest_reg].payload == rob_index:
        digest = generate_digest(result_val, reg_type)
        register_tracking_table[dest_reg].payload = digest
        register_tracking_table[dest_reg].valid = 1
        register_tracking_table[dest_reg].decay_ctr = 256

function on_pipeline_squash(squashed_rob_indices: Set[uint14]):
    for r in 0..64:
        // If entry has pending ROB index of a squashed instruction, invalidate it
        if register_tracking_table[r].valid == 0 and squashed_rob_indices.contains(register_tracking_table[r].payload):
            register_tracking_table[r].payload = 0
            register_tracking_table[r].decay_ctr = 0
    // Note: completed instructions that wrote back before the squash retain valid digests!
